sys_script_include.script:
var AdmissionService = Class.create();

AdmissionService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether an Admission record exists.
     *
     * @param {String} admissionSysId
     * @return {Boolean}
     */
    admissionExists: function(admissionSysId) {

        if (this.validationUtils.isEmpty(admissionSysId)) {
            return false;
        }

        var admission = new GlideRecord(
            'x_2130921_caresy_0_admission'
        );

        if (!admission.isValid()) {
            gs.error(
                'AdmissionService: Admission table is invalid.'
            );
            return false;
        }

        return admission.get(admissionSysId);
    },

    /**
     * Retrieve an Admission record.
     *
     * @param {String} admissionSysId
     * @return {GlideRecord|null}
     */
    getAdmission: function(admissionSysId) {

        if (this.validationUtils.isEmpty(admissionSysId)) {
            return null;
        }

        var admission = new GlideRecord(
            'x_2130921_caresy_0_admission'
        );

        if (!admission.isValid()) {
            gs.error(
                'AdmissionService: Admission table is invalid.'
            );
            return null;
        }

        if (admission.get(admissionSysId)) {
            return admission;
        }

        return null;
    },

    /**
     * Check whether an Admission is currently active
     * according to its admission status.
     *
     * @param {String} admissionSysId
     * @return {Boolean}
     */
    isAdmissionActive: function(admissionSysId) {

        var admission = this.getAdmission(admissionSysId);

        if (!admission) {
            return false;
        }

        var status = admission.getValue('admission_status');

        return status == 'Admitted';
    },

    type: 'AdmissionService'
};
